import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.Boholvbs.js";const u=JSON.parse('{"title":"Config reference","description":"Every prioricode.json and tui.json configuration key with type, default, and behavior — agent, provider, mcp, permission, compaction, bashSandbox, hooks, skills, and more.","frontmatter":{"title":"Config reference","description":"Every prioricode.json and tui.json configuration key with type, default, and behavior — agent, provider, mcp, permission, compaction, bashSandbox, hooks, skills, and more."},"headers":[],"relativePath":"reference/config.md","filePath":"reference/config.md"}'),c={name:"reference/config.md"};function a(s,t,i,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<p>Product config: <code>prioricode.json</code> / <code>prioricode.jsonc</code> (merge rules on <a href="./../configure/files.html">this page</a>). Interface config: <code>tui.json</code> (on <a href="./../configure/tui.html">this page</a>). Types in shorthand: <code>bool</code>, <code>int</code>, <code>str</code>, <code>str[]</code>. Model refs are <code>&quot;provider/model&quot;</code> strings.</p><h2 id="top-level-keys" tabindex="-1">Top-level keys <a class="header-anchor" href="#top-level-keys" aria-label="Permalink to &quot;Top-level keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Type / values</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>$schema</code></td><td>str</td><td>seeded</td><td><code>https://prioricode.ai/config.json</code> for editor validation</td></tr><tr><td><code>shell</code></td><td>str</td><td><code>$SHELL</code></td><td>shell used for commands, <code>!</code> mode, hook spawning</td></tr><tr><td><code>logLevel</code></td><td><code>DEBUG</code>/<code>INFO</code>/<code>WARN</code>/<code>ERROR</code></td><td><code>INFO</code></td><td>also <code>--log-level</code></td></tr><tr><td><code>username</code></td><td>str</td><td>OS user</td><td>shown in the UI</td></tr><tr><td><code>default_agent</code></td><td>str</td><td><code>build</code></td><td>must be a visible primary agent</td></tr><tr><td><code>subagent_depth</code></td><td>int</td><td><code>1</code></td><td>how deep task-nested subagents may go</td></tr><tr><td><code>model</code> / <code>small_model</code></td><td>str</td><td>auto-resolution</td><td>primary vs background (title/summary) models</td></tr><tr><td><code>autoupdate</code></td><td><code>bool</code>/<code>&quot;notify&quot;</code></td><td><code>true</code></td><td>silent for patch bumps only (<a href="./../getting-started/install.html">install</a>)</td></tr><tr><td><code>share</code></td><td><code>&quot;manual&quot;</code>/<code>&quot;auto&quot;</code>/<code>&quot;disabled&quot;</code></td><td><code>manual</code></td><td><code>autoshare: true</code> (deprecated) ⇒ <code>auto</code></td></tr><tr><td><code>enterprise</code></td><td><code>{ url? }</code></td><td>—</td><td>self-hosted share service base (<a href="./../platforms/enterprise.html">enterprise</a>)</td></tr><tr><td><code>disabled_providers</code> / <code>enabled_providers</code></td><td>str[]</td><td>all enabled</td><td>provider ID lists</td></tr><tr><td><code>instructions</code></td><td>str[]</td><td>—</td><td>extra context files/globs/URLs (<a href="./../using/context.html">context</a>)</td></tr><tr><td><code>references</code></td><td>obj (git/local)</td><td>—</td><td>additional project dirs (<code>reference</code> deprecated)</td></tr><tr><td><code>watcher.ignore</code></td><td>str[]</td><td>—</td><td>file-watch exclusions</td></tr><tr><td><code>snapshot</code></td><td>bool</td><td><code>true</code></td><td>file snapshots powering undo/diffs</td></tr><tr><td><code>plugin</code></td><td><code>(str | [str, obj])[]</code></td><td>—</td><td>plugin specs (<a href="./../extending/plugins.html">plugins</a>)</td></tr><tr><td><code>tools</code></td><td><code>{ &lt;tool&gt;: bool }</code></td><td>all on</td><td>shorthand for blanket permission deny</td></tr><tr><td><code>layout</code></td><td><code>auto</code>/<code>stretch</code></td><td>—</td><td>deprecated</td></tr></tbody></table><h3 id="server" tabindex="-1"><code>server</code> <a class="header-anchor" href="#server" aria-label="Permalink to &quot;`server`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>port</code></td><td><code>0</code> (random)</td><td><code>--port</code> overrides</td></tr><tr><td><code>hostname</code></td><td><code>127.0.0.1</code></td><td><code>--mdns</code> forces <code>0.0.0.0</code></td></tr><tr><td><code>mdns</code> / <code>mdnsDomain</code></td><td><code>false</code> / <code>prioricode.local</code></td><td>discovery (<a href="./../platforms/server.html">server</a>)</td></tr><tr><td><code>cors</code></td><td><code>[]</code></td><td>allowed browser origins</td></tr></tbody></table><h3 id="command" tabindex="-1"><code>command</code> <a class="header-anchor" href="#command" aria-label="Permalink to &quot;`command`&quot;">​</a></h3><p>One entry per custom slash command: <code>{ description?, agent?, model?, variant?, subtask?, template }</code> — normally authored as markdown in <code>commands/</code> (<a href="./../extending/commands.html">custom commands</a>).</p><h3 id="agent" tabindex="-1"><code>agent</code> <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;`agent`&quot;">​</a></h3><p><code>agent.&lt;name&gt;</code> configures built-ins or adds custom ones:</p><table tabindex="0"><thead><tr><th>Key</th><th>Values</th><th>Notes</th></tr></thead><tbody><tr><td><code>description</code></td><td>str</td><td>picker copy</td></tr><tr><td><code>mode</code></td><td><code>primary</code>/<code>subagent</code>/<code>all</code></td><td>where it can live</td></tr><tr><td><code>model</code>, <code>variant</code></td><td>str</td><td>overrides; subagents fall back to the caller&#39;s</td></tr><tr><td><code>temperature</code>, <code>top_p</code></td><td>number</td><td>sampling</td></tr><tr><td><code>prompt</code></td><td>str/inline</td><td>system prompt (markdown body elsewhere)</td></tr><tr><td><code>permission</code></td><td>permission obj</td><td>ruleset for this agent (<a href="./../using/permissions.html">grammar</a>)</td></tr><tr><td><code>steps</code></td><td>int</td><td>max agentic steps</td></tr><tr><td><code>hidden</code></td><td>bool</td><td>out of pickers</td></tr><tr><td><code>color</code></td><td><code>#hex</code> or theme color name</td><td>UI accent</td></tr><tr><td><code>disable</code></td><td>bool</td><td>remove the agent entirely</td></tr><tr><td><code>options</code></td><td>obj</td><td>passthrough provider options</td></tr></tbody></table><h3 id="provider" tabindex="-1"><code>provider</code> <a class="header-anchor" href="#provider" aria-label="Permalink to &quot;`provider`&quot;">​</a></h3><p><code>provider.&lt;id&gt;</code> — <code>{ api?, name?, env?[], npm?, whitelist?[], blacklist?[], options{ apiKey, baseURL, timeout(s), enterpriseUrl, setCacheKey, … }, models{ &lt;id&gt;{ name, limit{ context, output }, cost{ input, output, cache_read, cache_write }, attachment, reasoning, tool_call, interleaved, modalities, status, variants, headers, options, provider{ npm, api } } } }</code>. Anything the catalog doesn&#39;t know becomes true here (<a href="./../getting-started/providers.html">providers</a>).</p><h3 id="mcp" tabindex="-1"><code>mcp</code> <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;`mcp`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shape</th><th>Fields</th></tr></thead><tbody><tr><td>local</td><td><code>{ type: &quot;local&quot;, command: str[], cwd?, environment?, enabled?, timeout? }</code></td></tr><tr><td>remote</td><td><code>{ type: &quot;remote&quot;, url, headers?, oauth?{ clientId, clientSecret, scope, callbackPort (19876), redirectUri } | false, enabled?, timeout? }</code></td></tr><tr><td>toggle</td><td><code>{ enabled: bool }</code> against a name defined elsewhere</td></tr></tbody></table><p>Full behavior on the <a href="./../extending/mcp.html">MCP page</a>.</p><h3 id="permission" tabindex="-1"><code>permission</code> <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;`permission`&quot;">​</a></h3><p><code>&quot;allow&quot; | &quot;ask&quot; | &quot;deny&quot;</code> blanket, or <code>{ &quot;&lt;tool&gt;&quot;: action }</code>, or <code>{ &quot;&lt;tool&gt;&quot;: { &quot;&lt;glob-pattern&gt;&quot;: action } }</code>. Known tools: <code>read, edit, glob, grep, list, bash, task, external_directory, todowrite, question, webfetch, websearch, lsp, skill, doom_loop</code> + plan tools + arbitrary. Last match wins; <code>~</code>/<code>$HOME</code> expand. Also: <code>PRIORICODE_PERMISSION</code> (JSON, merged over file).</p><h3 id="bashsandbox" tabindex="-1"><code>bashSandbox</code> <a class="header-anchor" href="#bashsandbox" aria-label="Permalink to &quot;`bashSandbox`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Values</th><th>Default</th></tr></thead><tbody><tr><td><code>mode</code></td><td><code>off</code> / <code>best-effort</code> / <code>require</code></td><td><code>off</code></td></tr><tr><td><code>network</code></td><td><code>allow</code> / <code>deny</code></td><td><code>allow</code></td></tr><tr><td><code>writablePaths</code></td><td>str[]</td><td>project, worktree, git dir, data dir, tmp, npm/bun caches + these</td></tr></tbody></table><h3 id="hooks" tabindex="-1"><code>hooks</code> <a class="header-anchor" href="#hooks" aria-label="Permalink to &quot;`hooks`&quot;">​</a></h3><p><code>hooks.{PreToolUse,PostToolUse,SessionStart,Stop,Notification}</code> — arrays of <code>{ matcher? (wildcard tool name), command, timeout? seconds (30) }</code> (<a href="./../extending/hooks.html">hooks</a>).</p><h3 id="skills" tabindex="-1"><code>skills</code> <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;`skills`&quot;">​</a></h3><p><code>skills.paths</code> (dirs scanned for <code>**/SKILL.md</code>, <code>~</code>-expanded) + <code>skills.urls</code> (hosted packs via <code>index.json</code>) (<a href="./../extending/skills.html">skills</a>).</p><h3 id="formatter-lsp" tabindex="-1"><code>formatter</code> / <code>lsp</code> <a class="header-anchor" href="#formatter-lsp" aria-label="Permalink to &quot;`formatter` / `lsp`&quot;">​</a></h3><p><code>bool</code> or <code>{ &quot;&lt;id&gt;&quot;: { disabled?, command[], environment?, extensions? (required for custom), initialization? } }</code> (<a href="./../extending/formatters.html">formatters</a>, <a href="./../extending/lsp.html">LSP</a>).</p><h3 id="attachment-tool-output-compaction" tabindex="-1"><code>attachment</code> / <code>tool_output</code> / <code>compaction</code> <a class="header-anchor" href="#attachment-tool-output-compaction" aria-label="Permalink to &quot;`attachment` / `tool_output` / `compaction`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>attachment.image.auto_resize</code></td><td><code>true</code></td><td>downscale before send</td></tr><tr><td><code>attachment.image.max_width</code> / <code>max_height</code></td><td><code>2000</code></td><td>px</td></tr><tr><td><code>attachment.image.max_base64_bytes</code></td><td><code>5242880</code></td><td>5 MB</td></tr><tr><td><code>tool_output.max_lines</code></td><td><code>2000</code></td><td>truncation (<a href="./tools.html">tools</a>)</td></tr><tr><td><code>tool_output.max_bytes</code></td><td><code>51200</code></td><td>50 KB</td></tr><tr><td><code>compaction.auto</code></td><td><code>true</code></td><td>summarize near context limit</td></tr><tr><td><code>compaction.prune</code></td><td><code>false</code></td><td>drop stale tool output</td></tr><tr><td><code>compaction.threshold</code></td><td>—</td><td>percent trigger 1–100</td></tr><tr><td><code>compaction.default_context</code></td><td><code>128000</code></td><td>fallback window</td></tr><tr><td><code>compaction.tail_turns</code> / <code>preserve_recent_tokens</code> / <code>reserved</code></td><td>—</td><td>how much survives verbatim</td></tr></tbody></table><h3 id="experimental" tabindex="-1"><code>experimental</code> <a class="header-anchor" href="#experimental" aria-label="Permalink to &quot;`experimental`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Notes</th></tr></thead><tbody><tr><td><code>disable_paste_summary</code></td><td>no <code>[Pasted ~N]</code> collapsing</td></tr><tr><td><code>batch_tool</code></td><td>batched tool availability</td></tr><tr><td><code>openTelemetry</code></td><td>AI SDK spans for your OTLP collector</td></tr><tr><td><code>primary_tools[]</code></td><td>tools forced into the primary set</td></tr><tr><td><code>continue_loop_on_deny</code></td><td>keep looping after denials</td></tr><tr><td><code>mcp_timeout</code></td><td>MCP fallback timeout</td></tr><tr><td><code>policies[]</code></td><td>policy definitions (v2 surface)</td></tr></tbody></table><h2 id="tui-json-keys" tabindex="-1"><code>tui.json</code> keys <a class="header-anchor" href="#tui-json-keys" aria-label="Permalink to &quot;`tui.json` keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Type/values</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>theme</code></td><td>str (theme name)</td><td><code>prioricode</code></td><td>custom via <code>themes/*.json</code>; <code>system</code> follows terminal colors</td></tr><tr><td><code>keybinds</code></td><td>map id → binding</td><td>registry defaults</td><td><a href="./keybinds.html">keybind reference</a></td></tr><tr><td><code>leader_timeout</code></td><td>ms</td><td><code>2000</code></td><td>leader chord window</td></tr><tr><td><code>attention</code></td><td><code>{ enabled(false), notifications(true), sound(true), volume(0.4), sound_pack, sounds{default,question,permission,error,done,subagent_done} }</code></td><td>as marked</td><td>opt-in attention layer</td></tr><tr><td><code>prompt</code></td><td><code>{ max_height?, max_width? | &quot;auto&quot; }</code></td><td>auto</td><td>composer bounds</td></tr><tr><td><code>scroll_speed</code></td><td>number ≥0.001</td><td>built-in</td><td>wheel feel</td></tr><tr><td><code>scroll_acceleration</code></td><td><code>{ enabled }</code></td><td>—</td><td>trackpad acceleration</td></tr><tr><td><code>diff_style</code></td><td><code>auto</code>/<code>stacked</code></td><td><code>auto</code></td><td>diff layout</td></tr><tr><td><code>cursor</code></td><td><code>{ style: block/underline/line/default, blinking }</code></td><td>terminal</td><td>prompt cursor</td></tr><tr><td><code>mouse</code></td><td>bool</td><td><code>true</code></td><td>mouse capture (env override exists)</td></tr><tr><td><code>plugin</code> / <code>plugin_enabled</code></td><td>str[] / map</td><td>—</td><td>TUI-side plugins (<a href="./../extending/plugins.html">plugins</a>)</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../configure/files.html">Config discovery</a> — Merge order, substitution, managed layers. <ul><li><a href="./../using/permissions.html">Permissions</a> — The rules engine behind <code>permission</code>.</li><li><a href="./environment-variables.html">Env vars</a> — Runtime switches config can&#39;t reach.</li></ul></li></ul>',33)])])}const p=e(c,[["render",a]]);export{u as __pageData,p as default};
